/* IDxcCompilerArgs::GetArguments */
int32_t __cdecl xdxb_compilerargs_get_arguments(void* self, unsigned char* out_data, int32_t out_cap, unsigned char* out_len, unsigned char* out_count)
{
  const wchar_t** arr;
  uint32_t n;
  uint32_t i;
  if (!self) { xdxb_set_err("IDxcCompilerArgs::GetArguments: null object"); return 2; }
  arr = ((const XdxbIDxcCompilerArgsVtbl*)(*(void***)self))->GetArguments((void*)self);
  n = ((const XdxbIDxcCompilerArgsVtbl*)(*(void***)self))->GetCount((void*)self);
  if (out_count) xdxb_put_u32(out_count, n);
  { int32_t written = 0;
    for (i = 0; i < n && arr && arr[i]; i++) {
      int32_t need;
      if (i > 0) { if (out_data && written < out_cap) out_data[written] = (unsigned char)'\n'; written++; }
      need = xdxb_utf8_from_utf16(arr[i], (int32_t)wcslen(arr[i]), 0, 0);
      if (out_data && written < out_cap) {
        int32_t room = out_cap - written;
        xdxb_utf8_from_utf16(arr[i], (int32_t)wcslen(arr[i]), out_data + written, room);
        written += (need < room) ? need : room;
      } else { written += need; }
    }
    if (out_len) xdxb_put_u32(out_len, (uint32_t)written); }
  return 0;
}
